window.AUTH=window.AUTH||{};window.AUTH["23-852"]={"d":"23-852","id":"2024/23-852","n":"Bondi v. VanDerStok","briefs":[{"k":"petitioner","label":"Brief of petitioners Merrick B. Garland, Attorney General, et al.","date":"2024-06-25","url":"https://www.supremecourt.gov/DocketPDF/23/23-852/315742/20240625172334020_23-852%20VanDerStok.pdf","side":"pet","n":47},{"k":"respondent","label":"Brief of respondents Jennifer VanDerStok, et al.","date":"2024-08-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-852/322322/20240813115005305_23-852%20Brief%20of%20Respondents.pdf","side":"res","n":35},{"k":"respondent","label":"Brief of respondents Defense Distributed; Polymer 80, Inc., et al.","date":"2024-08-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-852/322352/20240813142012776_Brief%20of%20Respondents%20Defense%20Distributed%20SAF%20et%20al.pdf","side":"res","n":44},{"k":"reply","label":"Reply of petitioners Merrick B. Garland, Attorney General, et al.","date":"2024-09-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-852/325811/20240912141001784_23-852rbUnitedStates.pdf","side":"pet","n":14}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r20_q8l1.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"0":"4, 41, 42, 44, 46","1":"23, 42, 43","3":"17, 18"},"q":[{"src":"brief","b":0,"text":"to assist law enforcement authorities in investigating serious crimes.","cite":"573 U.S. 169, 180"},{"src":"brief","b":0,"text":"When police officers retrieve a gun at a crime scene, they can trace it to the buyer and consider him as a suspect.","cite":"573 U.S. at 182"},{"src":"brief","b":3,"text":"undermine—indeed, for all important purposes, would virtually repeal—the gun law’s core provisions.","cite":"573 U.S. at 179"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"guns out of the hands of criminals.","cite":"573 U. S. 169, 180"},{"src":"argument","who":"General Prelogar","text":"And I think it brings this case squarely within cases like Abramski, where, as you know, Justice Kagan, the -- the Court recognized that if you have an interpretation of the Gun Control Act that is going to allow that entire circumvention and essentially nullify the Act's requirements, the statute shouldn't properly be interpreted that way."},{"src":"argument","who":"Justice Kagan","text":"That was a close case. You maybe want this to be a stronger case than Abramski."},{"src":"argument","who":"Mr. Patterson","text":"And as this Court said in Abramski, which has already been referenced, Congress, in the Gun Control Act, did not seek to pursue its purposes of controlling access to firearms to the nth degree."}]},{"t":"case","label":"(V) Cases—Continued: Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"the statute [is] genuinely susceptible to two constructions after, and not before, its complexities are unraveled.","cite":"523 U.S. 224, 238"}]},{"t":"case","label":"Barrett v. United States","cite":"423 U.S. 212","y":1976,"id":"1975/74-5566","sc":1,"by":{"0":"42","1":"43"}},{"t":"case","label":"California v. ATF","cite":"2024 WL 779604","y":2024,"court":"N.D. Cal. Feb. 26","by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"conditions and qualifications on the commercial sale of arms,","cite":"2024 WL 779604"}]},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"by":{"0":"11, 46","3":"20"},"q":[{"src":"brief","b":0,"text":"conditions and qualifications on the commercial sale of arms.","cite":"554 U.S. at 627"}]},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"584 U.S. 79","y":2018,"id":"2017/16-1362","sc":1,"by":{"0":"38"},"q":[{"src":"opinion","who":"Justice Thomas, dissenting","text":"`we give [each] term its ordinary meaning.'","cite":"584 U. S. 79, 85"}]},{"t":"case","label":"Garland v. Cargill","cite":"2024 WL 2981505","y":2024,"court":"U.S. June 14","by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"draws a line more narrowly than one of [the Act’s] conceivable statutory purposes might suggest.","cite":"2024 WL 2981505"}]},{"t":"case","label":"Huddleston v. United States","cite":"415 U.S. 814","y":1974,"id":"1973/72-1076","sc":1,"by":{"0":"42","1":"43, 44"}},{"t":"case","label":"Iancu v. Brunetti","cite":"588 U.S. 388","y":2019,"id":"2018/18-302","sc":1,"by":{"0":"46"}},{"t":"case","label":"INS v. National Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"by":{"0":"27, 28"},"q":[{"src":"brief","b":0,"text":"does not mean that the regulation is facially invalid.","cite":"502 U.S. 183, 188"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"the possibility that [ATF's regulation] `may be invalid as applied' in some cases `does not mean that the regulation is facially invalid.' Instead, [the plaintiffs'] burden is to show that the Rule itself is inconsistent with the statute on its face.","cite":"502 U. S. 183, 188"}]},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"48","2":"24, 26, 27"},"q":[{"src":"brief","b":2,"text":"squarely contradict the theory that a vague provision is constitutional merely because there is some conduct that clearly falls within the provision’s grasp.","cite":"576 U.S. at 602"}]},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"does not foreclose it from using different language to accomplish that same goal","cite":"599 U.S. 382, 395"}]},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"comes into operation at the end of the process","cite":"570 U.S. 48, 76"}]},{"t":"case","label":"Maui v. Hawaii Wildlife Fund","cite":"590 U.S. 165","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/165/","sc":1,"by":{"0":"45"}},{"t":"case","label":"New York State Rifle & Pistol Ass’n v. Bruen","cite":"597 U.S. 1","y":2022,"id":"2021/20-843","sc":1,"by":{"0":"46","2":"28, 31"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"Well, I -- if you have something textual, I'd love for you to point me to that and also address -- your friends on the other side I'm sure are going to make something of this, that as recently as 2021, in a brief filed in the Southern District of New York, the government represented that an unfinished frame or receiver does not meet the statutory definition of \"firearm.\""}]},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"by":{"0":"45, 46"},"q":[{"src":"brief","b":0,"text":"‘can make no more than a guess as to what Congress intended,’","cite":"578 U.S. 282, 295 n.8"}]},{"t":"case","label":"Pugin v. Garland","cite":"599 U.S. 600","y":2023,"id":"2022/22-23","sc":1,"by":{"0":"41"}},{"t":"case","label":"United States v. Quiroz","cite":"449 F.2d 583","y":1971,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/449/583/","by":{"0":"48"}},{"t":"case","label":"United States v. Rahimi","cite":"2024 WL 3074728","y":2024,"court":"U.S. June 21","by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"left the panel slaying a straw man.","cite":"2024 WL 3074728"}]},{"t":"case","label":"United States v. Ryles","cite":"988 F.2d 13","y":1993,"url":"https://www.courtlistener.com/c/F.2d/988/13/","by":{"0":"14","1":"37"}},{"t":"case","label":"United States v. 16,179 Molso Italian .22 Caliber Winlee Derringer Convertible Starter Guns","cite":"443 F.2d 463","y":1971,"url":"https://www.courtlistener.com/c/F.2d/443/463/","by":{"0":"48","1":"18, 39, 40"}},{"t":"case","label":"United States v. Stewart","cite":"451 F.3d 1071","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/451/1071/","by":{"0":"24","1":"37, 38"}},{"t":"case","label":"United States v. Wick","cite":"697 Fed. Appx. 507","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./697/507/","by":{"0":"24"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"the mere fact that close case[s] can be envisioned renders a statute vague.","cite":"553 U.S. 285, 305-306"}]},{"t":"const","label":"Amendment II","clauses":[["second-amendment","Second Amendment"]],"text":"A well regulated Militia, being necessary to the security of a free State, the right of the people to keep and bear Arms, shall not be infringed.","by":{"0":"47"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(3)","(a)(3)(A)","(a)(3)(B)","(a)(3)(C)","(a)(3)(D)","(a)(4)(C)","(a)(25)","(a)(30)(B)","(a)(2)","(a)(30)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 3, 8, 15, 18-21, 25, 26, 28-31, 37, 38, 48, 8, 15, 18-21, 25, 26, 28-31, 37, 38, 48, 4, 17, 18, 30, 31, 38, 31, 31, 3, 3, 3","1":"5","2":"2, 13, 16, 2, 11, 13, 14, 15, 16, 18, 15, 17, 15, 17, 20, 18, 20, 20, 20","3":"9, 2-7, 9, 22, 2, 6, 7, 9, 10, 12, 22, 7"},"q":[{"src":"brief","b":0,"text":"(A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device.","cite":"18 U.S.C. 921(a)(3)"},{"src":"brief","b":0,"text":"the frame or receiver of any such weapon,","cite":"18 U.S.C. 921(a)(3)(B)"},{"src":"brief","b":1,"text":"designed to or may readily be converted to expel a projectile,","cite":"18 U.S.C. § 921(a)(3)(A)"},{"src":"brief","b":1,"text":"(B) the frame or receiver of any such weapon.","cite":"18 U.S.C. § 921(a)(3)(A)"},{"src":"brief","b":3,"text":"may readily be converted to expel a projectile by the action of an explosive.","cite":"18 U.S.C. 921(a)(3)(A)"},{"src":"brief","b":3,"text":"any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive.","cite":"18 U.S.C. 921(a)(3)(A)"}]},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(t)"],"by":{"0":"3, 3"}},{"t":"usc","label":"18 U.S.C. § 923","url":"https://www.law.cornell.edu/uscode/text/18/923","subs":["(a)","(g)(1)(A)","(i)"],"stext":{"head":"§923. Licensing","paras":[[0,"(a) No person shall engage in the business of importing, manufacturing, or dealing in firearms, or importing or manufacturing ammunition, until he has filed an application with and received a license to do so from the Attorney General. The application shall be in such form and contain only that information necessary to determine eligibility for licensing as the Attorney General shall by regulation prescribe and shall include a photograph and fingerprints of the applicant. Each applicant shall pay a fee for obtaining such a license, a separate fee being required for each place in which the applicant is to do business, as follows:"],[0,"(1) If the applicant is a manufacturer—"],[1,"(A) of destructive devices, ammunition for destructive devices or armor piercing ammunition, a fee of $1,000 per year;"],[1,"(B) of firearms other than destructive devices, a fee of $50 per year; or"],[1,"(C) of ammunition for firearms, other than ammunition for destructive devices or armor piercing ammunition, a fee of $10 per year."],[0,"(2) If the applicant is an importer—"],[1,"(A) of destructive devices, ammunition for destructive devices or armor piercing ammunition, a fee of $1,000 per year; or"],[1,"(B) of firearms other than destructive devices or ammunition for firearms other than destructive devices, or ammunition other than armor piercing ammunition, a fee of $50 per year."],[0,"(3) If the applicant is a dealer—"],[1,"(A) in destructive devices or ammunition for destructive devices, a fee of $1,000 per year; or"],[1,"(B) who is not a dealer in destructive devices, a fee of $200 for 3 years, except that the fee for renewal of a valid license shall be $90 for 3 years."],[0,"(b) Any person desiring to be licensed as a collector shall file an application for such license with the Attorney General. The application shall be in such form and contain only that information necessary to determine eligibility as the Attorney General shall by regulation prescribe. The fee for such license shall be $10 per year. Any license granted under this subsection shall only apply to transactions in curios and relics."],[0,"(c) Upon the filing of a proper application and payment of the prescribed fee, the Attorney General shall issue to a qualified applicant the appropriate license which, subject to the provisions of this chapter and other applicable provisions of law, shall entitle the licensee to transport, ship, and receive firearms and ammunition covered by such license in interstate or foreign commerce during the period stated in the license. Nothing in this chapter shall be construed to prohibit a licensed manufacturer, importer, or dealer from maintaining and disposing of a personal collection of firearms, subject only to such restrictions as apply in this chapter to dispositions by a person other than a licensed manufacturer, importer, or dealer. If any firearm is so disposed of by a licensee within one year after its transfer from his business inventory into such licensee's personal collection or if such disposition or any other acquisition is made for the purpose of willfully evading the restrictions placed upon licensees by this chapter, then such firearm shall be deemed part of such licensee's business inventory, except that any licensed manufacturer, importer, or dealer who has maintained a firearm as part of a personal collection for one year and who sells or otherwise disposes of such firearm shall record the description of the firearm in a bound volume, containing the name and place of residence and date of birth of the transferee if the transferee is an individual, or the identity and principal and local places of business of the transferee if the transferee is a corporation or other business entity: Provided, That no other recordkeeping shall be required."],[0,"(d)(1) Any application submitted under subsection (a) or (b) of this section shall be approved if—"],[1,"(A) the applicant is twenty-one years of age or over;"],[1,"(B) the applicant (including, in the case of a corporation, partnership, or association, any individual possessing, directly or indirectly, the power to direct or cause the direction of the management and policies of the corporation, partnership, or association) is not prohibited from transporting, shipping, or receiving firearms or ammunition in interstate or foreign commerce under section 922(g) and (n) of this chapter;"],[1,"(C) the applicant has not willfully violated any of the provisions of this chapter or regulations issued thereunder;"],[1,"(D) the applicant has not willfully failed to disclose any material information required, or has not made any false statement as to any material fact, in connection with his application;"],[1,"(E) the applicant has in a State (i) premises from which he conducts business subject to license under this chapter or from which he intends to conduct such business within a reasonable period of time, or (ii) in the case of a collector, premises from which he conducts his collecting subject to license under this chapter or from which he intends to conduct such collecting within a reasonable period of time;"],[1,"(F) the applicant certifies that—"],[2,"(i) the business to be conducted under the license is not prohibited by State or local law in the place where the licensed premise is located;"],[2,"(ii)(I) within 30 days after the application is approved the business will comply with the requirements of State and local law applicable to the conduct of the business; and"],[2,"(II) the business will not be conducted under the license until the requirements of State and local law applicable to the business have been met; and"],[2,"(iii) that the applicant has sent or delivered a form to be prescribed by the Attorney General, to the chief law enforcement officer of the locality in which the premises are located, which indicates that the applicant intends to apply for a Federal firearms license; and"],[1,"(G) in the case of an application to be licensed as a dealer, the applicant certifies that secure gun storage or safety devices will be available at any place in which firearms are sold under the license to persons who are not licensees (subject to the exception that in any case in which a secure gun storage or safety device is temporarily unavailable because of theft, casualty loss, consumer sales, backorders from a manufacturer, or any other similar reason beyond the control of the licensee, the dealer shall not be considered to be in violation of the requirement under this subparagraph to make available such a device)."],[0,"(2) The Attorney General must approve or deny an application for a license within the 60-day period beginning on the date it is received. If the Attorney General fails to act within such period, the applicant may file an action under section 1361 of title 28 to compel the Attorney General to act. If the Attorney General approves an applicant's application, such applicant shall be issued a license upon the payment of the prescribed fee."],[0,"(e) The Attorney General may, after notice and opportunity for hearing, revoke any license issued under this section if the holder of such license has willfully violated any provision of this chapter or any rule or regulation prescribed by the Attorney General under this chapter or fails to have secure gun storage or safety devices available at any place in which firearms are sold under the license to persons who are not licensees (except that in any case in which a secure gun storage or safety device is temporarily unavailable because of theft, casualty loss, consumer sales, backorders from a manufacturer, or any other similar reason beyond the control of the licensee, the dealer shall not be considered to be in violation of the requirement to make available such a device). The Attorney General may, after notice and opportunity for hearing, revoke the license of a dealer who willfully transfers armor piercing ammunition. The Secretary's 1 action under this subsection may be reviewed only as provided in subsection (f) of this section."],[0,"(f)(1) Any person whose application for a license is denied and any holder of a license which is revoked shall receive a written notice from the Attorney General stating specifically the grounds upon which the application was denied or upon which the license was revoked. Any notice of a revocation of a license shall be given to the holder of such license before the effective date of the revocation."],[0,"(2) If the Attorney General denies an application for, or revokes, a license, he shall, upon request by the aggrieved party, promptly hold a hearing to review his denial or revocation. In the case of a revocation of a license, the Attorney General shall upon the request of the holder of the license stay the effective date of the revocation. A hearing held under this paragraph shall be held at a location convenient to the aggrieved party."],[0,"(3) If after a hearing held under paragraph (2) the Attorney General decides not to reverse his decision to deny an application or revoke a license, the Attorney General shall give notice of his decision to the aggrieved party. The aggrieved party may at any time within sixty days after the date notice was given under this paragraph file a petition with the United States district court for the district in which he resides or has his principal place of business for a de novo judicial review of such denial or revocation. In a proceeding conducted under this subsection, the court may consider any evidence submitted by the parties to the proceeding whether or not such evidence was considered at the hearing held under paragraph (2). If the court decides that the Attorney General was not authorized to deny the application or to revoke the license, the court shall order the Attorney General to take such action as may be necessary to comply with the judgment of the court."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/923?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 3, 12, 3, 4, 31","2":"1","3":"7"}},{"t":"usc","label":"18 U.S.C. § 926","url":"https://www.law.cornell.edu/uscode/text/18/926","subs":["(a)"],"stext":{"head":"§926. Rules and regulations","paras":[[0,"(a) The Attorney General may prescribe only such rules and regulations as are necessary to carry out the provisions of this chapter, including—"],[1,"(1) regulations providing that a person licensed under this chapter, when dealing with another person so licensed, shall provide such other licensed person a certified copy of this license;"],[1,"(2) regulations providing for the issuance, at a reasonable cost, to a person licensed under this chapter, of certified copies of his license for use as provided under regulations issued under paragraph (1) of this subsection; and"],[1,"(3) regulations providing for effective receipt and secure storage of firearms relinquished by or seized from persons described in subsection (d)(8) or (g)(8) of section 922."],[0,"No such rule or regulation prescribed after the date of the enactment of the Firearms Owners' Protection Act may require that records required to be maintained under this chapter or any portion of the contents of such records, be recorded at or transferred to a facility owned, managed, or controlled by the United States or any State or any political subdivision thereof, nor that any system of registration of firearms, firearms owners, or firearms transactions or dispositions be established. Nothing in this section expands or restricts the Secretary's 1 authority to inquire into the disposition of any firearm in the course of a criminal investigation."],[0,"(b) The Attorney General shall give not less than ninety days public notice, and shall afford interested parties opportunity for hearing, before prescribing such rules and regulations."],[0,"(c) The Attorney General shall not prescribe rules or regulations that require purchasers of black powder under the exemption provided in section 845(a)(5) of this title to complete affidavits or forms attesting to that exemption."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/926?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"such rules and regulations as are necessary to carry out","cite":"18 U.S.C. 926(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"rules and regulations as are necessary to carry out","cite":"18 U. S. C. § 926(a)"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"prescribe only such rules and regulations as are necessary to carry out","cite":"18 U. S. C. § 926(a)"}]},{"t":"usc","label":"26 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/26/5845","subs":["(b)","(c)","(d)"],"stext":{"head":"§5845. Definitions","paras":[[0,"For the purpose of this chapter—"],[0,"(a) Firearm"],[0,"The term \"firearm\" means (1) a shotgun having a barrel or barrels of less than 18 inches in length; (2) a weapon made from a shotgun if such weapon as modified has an overall length of less than 26 inches or a barrel or barrels of less than 18 inches in length; (3) a rifle having a barrel or barrels of less than 16 inches in length; (4) a weapon made from a rifle if such weapon as modified has an overall length of less than 26 inches or a barrel or barrels of less than 16 inches in length; (5) any other weapon, as defined in subsection (e); (6) a machinegun; (7) any silencer (as defined in section 921 of title 18, United States Code); and (8) a destructive device. The term \"firearm\" shall not include an antique firearm or any device (other than a machinegun or destructive device) which, although designed as a weapon, the Secretary finds by reason of the date of its manufacture, value, design, and other characteristics is primarily a collector's item and is not likely to be used as a weapon."],[0,"(b) Machinegun"],[0,"The term \"machinegun\" means any weapon which shoots, is designed to shoot, or can be readily restored to shoot, automatically more than one shot, without manual reloading, by a single function of the trigger. The term shall also include the frame or receiver of any such weapon, any part designed and intended solely and exclusively, or combination of parts designed and intended, for use in converting a weapon into a machinegun, and any combination of parts from which a machinegun can be assembled if such parts are in the possession or under the control of a person."],[0,"(c) Rifle"],[0,"The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of the explosive in a fixed cartridge to fire only a single projectile through a rifled bore for each single pull of the trigger, and shall include any such weapon which may be readily restored to fire a fixed cartridge."],[0,"(d) Shotgun"],[0,"The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of the explosive in a fixed shotgun shell to fire through a smooth bore either a number of projectiles (ball shot) or a single projectile for each pull of the trigger, and shall include any such weapon which may be readily restored to fire a fixed shotgun shell."],[0,"(e) Any other weapon"],[0,"The term \"any other weapon\" means any weapon or device capable of being concealed on the person from which a shot can be discharged through the energy of an explosive, a pistol or revolver having a barrel with a smooth bore designed or redesigned to fire a fixed shotgun shell, weapons with combination shotgun and rifle barrels 12 inches or more, less than 18 inches in length, from which only a single discharge can be made from either barrel without manual reloading, and shall include any such weapon which may be readily restored to fire. Such term shall not include a pistol or a revolver having a rifled bore, or rifled bores, or weapons designed, made, or intended to be fired from the shoulder and not capable of firing fixed ammunition."],[0,"(f) Destructive device"],[0,"The term \"destructive device\" means (1) any explosive, incendiary, or poison gas (A) bomb, (B) grenade, (C) rocket having a propellent charge of more than four ounces, (D) missile having an explosive or incendiary charge of more than one-quarter ounce, (E) mine, or (F) similar device; (2) any type of weapon by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, the barrel or barrels of which have a bore of more than one-half inch in diameter, except a shotgun or shotgun shell which the Secretary finds is generally recognized as particularly suitable for sporting purposes; and (3) any combination of parts either designed or intended for use in converting any device into a destructive device as defined in subparagraphs (1) and (2) and from which a destructive device may be readily assembled. The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10, United States Code; or any other device which the Secretary finds is not likely to be used as a weapon, or is an antique or is a rifle which the owner intends to use solely for sporting purposes."],[0,"(g) Antique firearm"],[0,"The term \"antique firearm\" means any firearm not designed or redesigned for using rim fire or conventional center fire ignition with fixed ammunition and manufactured in or before 1898 (including any matchlock, flintlock, percussion cap, or similar type of ignition system or replica thereof, whether actually manufactured before or after the year 1898) and also any firearm using fixed ammunition manufactured in or before 1898, for which ammunition is no longer manufactured in the United States and is not readily available in the ordinary channels of commercial trade."],[0,"(h) Unserviceable firearm"],[0,"The term \"unserviceable firearm\" means a firearm which is incapable of discharging a shot by means of an explosive and incapable of being readily restored to a firing condition."],[0,"(i) Make"],[0,"The term \"make\", and the various derivatives of such word, shall include manufacturing (other than by one qualified to engage in such business under this chapter), putting together, altering, any combination of these, or otherwise producing a firearm."],[0,"(j) Transfer"],[0,"The term \"transfer\" and the various derivatives of such word, shall include selling, assigning, pledging, leasing, loaning, giving away, or otherwise disposing of."],[0,"(k) Dealer"],[0,"The term \"dealer\" means any person, not a manufacturer or importer, engaged in the business of selling, renting, leasing, or loaning firearms and shall include pawnbrokers who accept firearms as collateral for loans."],[0,"(l) Importer"],[0,"The term \"importer\" means any person who is engaged in the business of importing or bringing firearms into the United States."],[0,"(m) Manufacturer"],[0,"The term \"manufacturer\" means any person who is engaged in the business of manufacturing firearms."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/5845?type=usc&year=mostrecent&link-type=html"},"by":{"0":"38, 38, 38","3":"10, 11"},"q":[{"src":"brief","b":0,"text":"any weapon which shoots, is designed to shoot, or can be readily restored to shoot, automatically more than one shot, without manual reloading, by a single function of the trigger,","cite":"26 U.S.C. 5845(b)"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"the frame or receiver of any such weapon.","cite":"26 U. S. C. § 5845(b)"}]},{"t":"reg","label":"28 C.F.R. § 0.130","url":"https://www.ecfr.gov/current/title-28/section-0.130","subs":["(a)"],"by":{"0":"5","1":"6"}},{"t":"reg","label":"33 Fed. Reg. 18,555","url":"https://www.govinfo.gov/link/fr/33/18555","by":{"0":"8","2":"3"}},{"t":"reg","label":"87 Fed. Reg. 24,652","url":"https://www.govinfo.gov/link/fr/87/24652","by":{"0":"4-10, 12, 13, 16, 17, 19, 21, 22","1":"9, 10, 15, 22, 24, 32, 39, 40, 42, 47","2":"3","3":"4, 12-14, 16, 17"}},{"t":"case","label":"Baxter Healthcare Corp. of Puerto Rico v. United States","cite":"998 F. Supp. 1133","y":1998,"court":"Ct. Int’l Trade","url":"https://www.courtlistener.com/c/F.%20Supp./998/1133/","by":{"1":"28"}},{"t":"case","label":"Collins v. Yellen","cite":"594 U.S. 1761","y":2021,"id":"2020/19-422","sc":1,"by":{"1":"20, 21"},"q":[{"src":"brief","b":1,"text":"[W]hen Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"594 U.S. 1761, 1782"}]},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"1":"19"}},{"t":"case","label":"Garland v. Cargill","cite":"602 U.S. 406","y":2024,"id":"2023/22-976","sc":1,"by":{"1":"22, 42","3":"18"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"by":{"1":"38, 39"},"q":[{"src":"brief","b":1,"text":"Vague laws may trap the innocent by not providing fair warning [and] if arbitrary and discriminatory enforcement is to be prevented, laws must provide explicit standards for those who apply them.","cite":"408 U.S. 104, 108–09"}]},{"t":"case","label":"Henson v. Santander Consumer USA, Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"1":"42","2":"12, 21, 22"},"q":[{"src":"brief","b":2,"text":"that [the] legislature says ... what it means and means ... what it says.","cite":"582 U.S. 79, 89"},{"src":"brief","b":2,"text":"In the end, reasonable people can disagree with how Congress balanced the various social costs and benefits in this area.","cite":"582 U.S. 79, 90"}]},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"When Congress acts to amend a statute, [this Court] presume[s] it intends its amendment[s] to have real and substantial effect.","cite":"140 S. Ct. 768, 779"}]},{"t":"case","label":"Iselin v. United States","cite":"270 U.S. 245","y":1926,"id":"scdb/1925-076","sc":1,"by":{"1":"21"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"[o]nce a federal claim is properly presented, a party can make any argument in support of that claim; parties are not limited to the precise arguments they made below.","cite":"513 U.S. 374, 379"}]},{"t":"case","label":"Loper Bright v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"by":{"1":"20","2":"19"},"q":[{"src":"brief","b":1,"text":"interpretations issued contemporaneously with the statute at issue, and which have remained consistent over time, may be especially useful in determining the statute’s meaning.","cite":"144 S. Ct. 2244, 2262–63"},{"src":"argument","who":"Justice Jackson","text":"Just, you know -- I mean, the agency still has the authority, I think. And, in Loper, Loper seemed to recognize that Congress may have given the agency the authority to make certain calls, right?"}]},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"by":{"1":"38","2":"25, 27"},"q":[{"src":"brief","b":1,"text":"[t]he prohibition of vagueness in criminal statutes … is an essential of due process, required by both ordinary notions of fair play and the settled rules of law.","cite":"138 S. Ct. 1204, 1212"},{"src":"brief","b":2,"text":"With its nonexclusive list of eight factors and lack of concrete examples, the Final Rule produces ‘more unpredictability and arbitrariness than the Due Process Clause tolerates.","cite":"138 S. Ct. 1204, 1215"},{"src":"brief","b":2,"text":"more unpredictability and arbitrariness than the Due Process Clause tolerates.","cite":"138 S. Ct. at 1215"}]},{"t":"case","label":"Shaw v. United States","cite":"580 U.S. 63","y":2016,"id":"2016/15-5991","sc":1,"by":{"1":"41"}},{"t":"case","label":"United States v. Annis","cite":"446 F.3d 852","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/852/","by":{"1":"18"}},{"t":"case","label":"United States v. Christmann","cite":"193 F.3d 1023","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/193/1023/","by":{"1":"18"}},{"t":"case","label":"United States v. Drasen","cite":"845 F.2d 731","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/845/731/","by":{"1":"5, 21"},"q":[{"src":"brief","b":1,"text":"In adding the ‘readily restored’ clause, Congress specifically intended to overcome [a decision] holding that a firearm with a missing firing pin was not a firearm under the Act.","cite":"845 F.2d at 736"}]},{"t":"case","label":"United States v. Jimenez","cite":"191 F. Supp. 3d 1038","y":2016,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/191/1038/","by":{"1":"10"}},{"t":"case","label":"United States v. One 1980 Chevrolet Corvette I.D. No. 12878AS411361","cite":"564 F. Supp. 347","y":1983,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./564/347/","by":{"1":"36"}},{"t":"case","label":"United States v. Rowold","cite":"429 F. Supp. 3d 469","y":2019,"court":"N.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/429/469/","by":{"1":"10, 32, 33"}},{"t":"case","label":"United States v. Thompson","cite":"202 F. Supp. 503","y":1962,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./202/503/","by":{"1":"4"},"q":[{"src":"brief","b":1,"text":"us[ing] the energy of the explosive in a fixed shotgun shell to fire [a projectile].","cite":"202 F. Supp. 503, 505 n.3"}]},{"t":"case","label":"United States v. Thompson/Ctr. Arms Co.","cite":"504 U.S. 505","y":1992,"id":"1991/91-164","sc":1,"by":{"1":"41","2":"23"}},{"t":"case","label":"United States v. Wick","cite":"697 F. App’x 507","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/697/507/","by":{"1":"37"}},{"t":"usc","label":"26 U.S.C. § 5842","url":"https://www.law.cornell.edu/uscode/text/26/5842","subs":["(a)"],"by":{"1":"37"}},{"t":"law","label":"An Act to Amend Chapter 44 (Relating to Firearms) of Title 18, United States Code, and for Other Purposes, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/449","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1213","by":{"1":"4, 5, 41","2":"1, 4","3":"3"}},{"t":"reg","label":"27 C.F.R. § 478.11","url":"https://www.ecfr.gov/current/title-27/section-478.11","by":{"1":"12, 33, 39","2":"3, 4, 14, 24"},"q":[{"src":"brief","b":1,"text":"a weapon parts kit that is designed to or may readily be completed, assembled, restored, or otherwise converted to expel a projectile by the action of an explosive.","cite":"27 C.F.R. § 478.11"}]},{"t":"reg","label":"26 C.F.R. pt. 178","url":"https://www.ecfr.gov/current/title-26/part-178","by":{"1":"6, 8, 20"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"by":{"2":"19"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"the rule exists in part to protect the Due Process Utilize a smart apostrophe promise that ‘a fair warning should be given to the world in language that the common world will understand, of what the law intends to do if a certain line is passed.’","cite":"598 U.S. 85, 102, 143"}]},{"t":"case","label":"Corner Post, Inc. v. Bd. of Governors of Fed. Reserve Sys.","cite":"144 S. Ct. 2440","y":2024,"id":"2023/22-1008","sc":1,"by":{"2":"14"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"shun an interpretation that raises serious constitutional doubts and instead may adopt an alternative that avoids those problems.","cite":"138 S. Ct. 830, 836"}]},{"t":"case","label":"McBoyle v. United States","cite":"283 U.S. 25","y":1931,"id":"scdb/1930-139","sc":1,"by":{"2":"23"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"not better just because it would go further.","cite":"601 U.S. 124, 152"}]},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"often criticized that last resort of extravagant interpretation, noting that no law pursues its purpose at all costs, and that the textual limitations upon a law's scope are no less a part of its ‘purpose’ than its substantive authorizations.","cite":"547 U.S. 715, 752"}]},{"t":"case","label":"Rutledge v. Pharm. Care Mgmt. Ass'n","cite":"592 U.S. 80","y":2020,"url":"https://supreme.justia.com/cases/federal/us/592/80/","sc":1,"by":{"2":"18"}},{"t":"case","label":"Tripoli Rocketry v. ATF","cite":"437 F.3d 75","url":"https://www.courtlistener.com/c/F.3d/437/75/","by":{"2":"25"}},{"t":"case","label":"United States v. Evans","cite":"333 U.S. 483","y":1948,"id":"scdb/1947-057","sc":1,"by":{"2":"27"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"When words have several plausible definitions, context differentiates among them.","cite":"599 U.S. 762, 775"}]},{"t":"case","label":"United States v. Lim","cite":"444 F.3d 910","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/910/","by":{"2":"25"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"2":"24, 32"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(C)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"by":{"2":"10, 11, 13, 23"},"q":[{"src":"brief","b":2,"text":"in excess of statutory jurisdiction, authority, or limitations, or short of statutory right,","cite":"5 U.S.C. § 706(2)(C)"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"in excess of statutory . . . authority.","cite":"5 U. S. C. § 706"}]},{"t":"usc","label":"10 U.S.C. § 7543","url":"https://www.law.cornell.edu/uscode/text/10/7543","by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 5402","url":"https://www.law.cornell.edu/uscode/text/15/5402","subs":["(6)(b)"],"by":{"2":"18"}},{"t":"usc","label":"19 U.S.C. § 1677j","url":"https://www.law.cornell.edu/uscode/text/19/1677j","by":{"2":"20"}},{"t":"usc","label":"19 U.S.C. § 1683b","url":"https://www.law.cornell.edu/uscode/text/19/1683b","by":{"2":"18"}},{"t":"usc","label":"19 U.S.C. § 2703","url":"https://www.law.cornell.edu/uscode/text/19/2703","by":{"2":"20"}},{"t":"usc","label":"19 U.S.C. § 3203","url":"https://www.law.cornell.edu/uscode/text/19/3203","by":{"2":"20"}},{"t":"usc","label":"19 U.S.C. § 3721","url":"https://www.law.cornell.edu/uscode/text/19/3721","by":{"2":"20"}},{"t":"usc","label":"28 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/28/5845","subs":["(b)"],"by":{"2":"18"}},{"t":"usc","label":"42 U.S.C. § 6295","url":"https://www.law.cornell.edu/uscode/text/42/6295","by":{"2":"18"}},{"t":"reg","label":"27 C.F.R. § 478.12","url":"https://www.ecfr.gov/current/title-27/section-478.12","subs":["(c)"],"by":{"2":"4, 14, 4, 15, 17, 24, 25, 26"},"q":[{"src":"brief","b":2,"text":"partially complete, disassembled, or nonfunctional frame or receiver, including a frame or receiver parts kit, that is designed to or may readily be completed, assembled, restored, or otherwise converted to function as a frame or receiver.","cite":"27 C.F.R. § 478.12(c)"},{"src":"brief","b":2,"text":"reached a stage of manufacture where it is clearly identifiable as an unfinished component part of a weapon (e.g., unformed block of metal, liquid polymer, or other raw material).","cite":"27 C.F.R. § 478.12(c)"}]},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"a particularly dangerous ground on which to rest an interpretation of a prior statute.","cite":"535 U.S. 274, 287"}]},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"by":{"3":"15"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"3":"20"}}]};